const logs = $input.all().map(i => i.json);

// Filter out non-rule events (engine cycle_ran, pull_success, etc.) — only fires.
const fires = logs.filter(l =>
  l.rule_id != null &&
  (String(l.action_taken || '').startsWith('would_have_') ||
   ['paused','scale_budgetd','decrease_budgetd','enabled','telegram_snooze','telegram_reenable','telegram_approve_pause'].includes(l.action_taken))
);

const parseTrigger = (json) => {
  if (!json) return {};
  try { return typeof json === 'string' ? JSON.parse(json) : json; } catch { return {}; }
};

return fires.map(f => {
  const m = parseTrigger(f.trigger_data_json);
  const firedIso = new Date(String(f.created_at).replace(' ', 'T') + (String(f.created_at).endsWith('Z') ? '' : 'Z')).toISOString();
  return {
    json: {
      fields: {
        'Fire ID': f.id,  // unique key for upsert dedup
        'Fired At': firedIso,
        'Rule ID': f.rule_id,
        'Entity Type': f.entity_type || '',
        'Entity ID': f.entity_id || '',
        'Entity Name': f.entity_name || '',
        'Action Taken': f.action_taken || '',
        'Dry Run': !!f.is_dry_run,
        'Spend Today': typeof m.spend_today === 'number' ? m.spend_today : null,
        'Conversions': typeof m.conversions === 'number' ? Math.round(m.conversions) : null,
        'CPA': typeof m.cpa === 'number' ? m.cpa : null,
        'ROI %': typeof m.roi === 'number' ? m.roi * 100 : null,
        'Trigger Snapshot': JSON.stringify(m).slice(0, 4000)
      }
    }
  };
});

const all = $input.all().map(i => i.json);
if (!all.length) return [];
const chunks = [];
for (let i = 0; i < all.length; i += 10) {
  chunks.push({ json: { records: all.slice(i, i + 10) } });
}
return chunks;
